"""Read-only summary of a node's workflow tables."""
import argparse
from datetime import datetime, timezone
import json
from pathlib import Path
import re

EVERY = re.compile(r"([1-9][0-9]*)([rsmhd])\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}
DAY_US = 86400 * 1000000


class RawInteger:
    """Preserve JSON integer digits without Python's decimal conversion limit."""

    def __init__(self, text):
        self.text = text


def encode(value):
    if isinstance(value, RawInteger):
        return value.text
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(key) + ":" + encode(item)
                              for key, item in value.items()) + "}"
    if isinstance(value, list):
        return "[" + ",".join(encode(item) for item in value) + "]"
    return json.dumps(value, separators=(",", ":"))


def reject_constant(value):
    raise ValueError("non-finite JSON number: " + value)


def read_table(node, table):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_int=RawInteger, parse_constant=reject_constant)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(column, str) for column in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    return stamp.replace(tzinfo=now.tzinfo) if stamp.tzinfo is None else stamp


def utc_microseconds(stamp):
    offset = stamp.utcoffset()
    if offset is None:
        raise ValueError("timezone required")
    local = ((stamp.toordinal() - 1) * DAY_US
             + (stamp.hour * 3600 + stamp.minute * 60 + stamp.second) * 1000000
             + stamp.microsecond)
    return local - (offset.days * DAY_US + offset.seconds * 1000000
                    + offset.microseconds)


def utc_text(microseconds):
    days, remainder = divmod(microseconds, DAY_US)
    date = datetime.fromordinal(days + 1)
    seconds = remainder // 1000000
    hour, seconds = divmod(seconds, 3600)
    minute, second = divmod(seconds, 60)
    return f"{date.year:04d}-{date.month:02d}-{date.day:02d}T{hour:02d}:{minute:02d}:{second:02d}Z"


def integer_code(text):
    digits = text.lstrip("+-").lstrip("0") or "0"
    normalized = ("-" if text.startswith("-") and digits != "0" else "") + digits
    return int(normalized) if len(digits) <= 4300 else RawInteger(normalized)


def routine(row, now):
    match = EVERY.fullmatch(row["every"])
    if match is None:
        raise ValueError("invalid every")
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif CODE.fullmatch(raw_code):
        code = integer_code(raw_code)
    else:
        raise ValueError("invalid last_code")
    raw_time = row["last_time"]
    stamp = timestamp(raw_time, now) if raw_time else None
    deadline = None
    next_time = None
    if stamp is not None and match.group(2) != "r":
        # Work in integer UTC microseconds so local-year boundaries cannot overflow.
        deadline = utc_microseconds(stamp) + int(match.group(1)) * SECONDS[match.group(2)] * 1000000
        next_time = utc_text(deadline)
    if code == "running":
        state = "running"
    elif stamp is None:
        state = "never"
    elif code is not None and code != 0:
        state = "failed"
    elif deadline is not None and utc_microseconds(now) >= deadline:
        state = "overdue"
    else:
        state = "ok"
    return {"name": row["name"], "every": row["every"],
            "last_time": raw_time if raw_time else None, "last_code": code,
            "state": state, "next": next_time}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = ("interrupted" if row["claimed"] else
             "due" if utc_microseconds(at) <= utc_microseconds(now) else "pending")
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": {key: 0 for key in
                                      ("running", "never", "failed", "overdue", "ok")},
                         "schedule": {key: 0 for key in
                                      ("interrupted", "due", "pending")}},
              "bad": []}
    for table, convert in (("routines", routine), ("schedule", scheduled)):
        rows, errors = read_table(node, table)
        result["bad"].extend(errors)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            duplicate = isinstance(name, str) and bool(name) and name in seen
            if isinstance(name, str) and name:
                seen.add(name)
            if duplicate:
                why = "dup_name"
            elif (not isinstance(row, dict) or not isinstance(name, str) or not name
                  or any(key not in row for key in REQUIRED[table])
                  or not all(isinstance(value, str) for value in row.values())):
                why = "bad_row"
            else:
                try:
                    item = convert(row, now)
                except (ValueError, OverflowError, TypeError):
                    why = "bad_row"
                else:
                    result[table].append(item)
                    result["counts"][table][item["state"]] += 1
                    continue
            result["bad"].append({"table": table, "row": index, "why": why})
        result[table].sort(key=lambda item: item["name"])
    result["bad"].sort(key=lambda item: (item["table"], -1 if item["row"] is None
                                          else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize workflow tables without writing")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        now = datetime.fromisoformat(args.now)
        if now.tzinfo is None or now.utcoffset() is None:
            raise ValueError("timezone required")
    except (ValueError, OverflowError):
        parser.error("--now must be a timezone-aware ISO datetime")
    print(encode(summarize(args.folder, now)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
